// Frame bytes are pinned to what v1's HunterRoam::startZone() produces. The
// expected values were generated by compiling v1's frame code (minus the bus
// write) on a host, so these tests prove v2 sends what v1 sent — and v1's
// frames are the ones known to work on this Pro-C.

#include <unity.h>

#include <cstring>

#include "hunter_frame.h"
#include "hunter_limits.h"

void setUp() {}
void tearDown() {}

namespace {

void assertFrame(const std::optional<hunter::Frame>& got,
                 const uint8_t (&want)[15]) {
  TEST_ASSERT_TRUE(got.has_value());
  TEST_ASSERT_EQUAL_UINT(15, got->length);
  TEST_ASSERT_TRUE(got->trailingOneBit);
  TEST_ASSERT_EQUAL_HEX8_ARRAY(want, got->bytes, 15);
}

}  // namespace

void test_zone1_5min() {
  const uint8_t want[15] = {0xff, 0x20, 0x00, 0x31, 0x51, 0x80, 0x12, 0x54,
                            0x90, 0x01, 0x95, 0x0c, 0x01, 0xb8, 0x3f};
  assertFrame(hunter::buildStartFrame(1, 5), want);
}

void test_zone12_30min_last_low_bank() {
  const uint8_t want[15] = {0xff, 0x20, 0x01, 0x88, 0xfc, 0x48, 0x7a, 0x3f,
                            0xd2, 0x1b, 0x8f, 0xdc, 0x81, 0xbe, 0xbf};
  assertFrame(hunter::buildStartFrame(12, 30), want);
}

void test_zone13_10min_first_high_bank() {
  const uint8_t want[15] = {0xff, 0x40, 0x00, 0x48, 0xb2, 0x40, 0x06, 0x2c,
                            0x30, 0x07, 0x8b, 0x3c, 0x01, 0xb9, 0xbf};
  assertFrame(hunter::buildStartFrame(13, 10), want);
}

void test_zone48_240min_both_maxima() {
  const uint8_t want[15] = {0xff, 0x40, 0x01, 0xc4, 0x1e, 0x2f, 0x65, 0x07,
                            0x2b, 0xdf, 0x41, 0xfa, 0xf1, 0xbf, 0xbf};
  assertFrame(hunter::buildStartFrame(48, 240), want);
}

void test_zone20_120min() {
  const uint8_t want[15] = {0xff, 0x40, 0x01, 0xa8, 0x3d, 0x4e, 0x76, 0x0f,
                            0xb3, 0x98, 0x43, 0xc2, 0xe1, 0xbe, 0x3f};
  assertFrame(hunter::buildStartFrame(20, 120), want);
}

void test_zone7_1min_minimum_duration() {
  const uint8_t want[15] = {0xff, 0x20, 0x00, 0xf1, 0x17, 0x80, 0x2a, 0x45,
                            0x50, 0x0d, 0x91, 0x6c, 0x01, 0xbb, 0x3f};
  assertFrame(hunter::buildStartFrame(7, 1), want);
}

void test_stop_zone1() {
  const uint8_t want[15] = {0xff, 0x20, 0x00, 0x30, 0x11, 0x80, 0x12, 0x04,
                            0x90, 0x01, 0x81, 0x0c, 0x01, 0xb8, 0x3f};
  assertFrame(hunter::buildStopFrame(1), want);
}

void test_stop_zone3() {
  const uint8_t want[15] = {0xff, 0x20, 0x00, 0xb0, 0x15, 0x80, 0x32, 0x05,
                            0x90, 0x09, 0x81, 0x4c, 0x01, 0xba, 0x3f};
  assertFrame(hunter::buildStopFrame(3), want);
}

void test_stop_zone48() {
  const uint8_t want[15] = {0xff, 0x40, 0x01, 0xc4, 0x1e, 0x20, 0x65, 0x07,
                            0x28, 0x1f, 0x41, 0xfa, 0x01, 0xbf, 0xbf};
  assertFrame(hunter::buildStopFrame(48), want);
}

void test_start_rejects_zero_minutes() {
  // Zero minutes is the stop command. A start must never produce it.
  TEST_ASSERT_FALSE(hunter::buildStartFrame(1, 0).has_value());
}

void test_start_rejects_out_of_range() {
  TEST_ASSERT_FALSE(hunter::buildStartFrame(hunter::kMinZone - 1, 5).has_value());
  TEST_ASSERT_FALSE(hunter::buildStartFrame(hunter::kMaxZone + 1, 5).has_value());
  TEST_ASSERT_FALSE(hunter::buildStartFrame(1, hunter::kMaxRunMinutes + 1).has_value());
  TEST_ASSERT_FALSE(hunter::buildStartFrame(1, -1).has_value());
  // 256 would wrap to 0 in an 8-bit field, turning a start into a stop.
  TEST_ASSERT_FALSE(hunter::buildStartFrame(1, 256).has_value());
}

void test_stop_rejects_out_of_range() {
  TEST_ASSERT_FALSE(hunter::buildStopFrame(0).has_value());
  TEST_ASSERT_FALSE(hunter::buildStopFrame(49).has_value());
}

void test_every_valid_start_differs_from_its_stop() {
  for (int zone = hunter::kMinZone; zone <= hunter::kMaxZone; ++zone) {
    const auto stop = hunter::buildStopFrame(zone);
    TEST_ASSERT_TRUE(stop.has_value());
    for (int m = hunter::kMinRunMinutes; m <= hunter::kMaxRunMinutes; ++m) {
      const auto start = hunter::buildStartFrame(zone, m);
      TEST_ASSERT_TRUE(start.has_value());
      TEST_ASSERT_NOT_EQUAL(0, memcmp(start->bytes, stop->bytes, 15));
    }
  }
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_zone1_5min);
  RUN_TEST(test_zone12_30min_last_low_bank);
  RUN_TEST(test_zone13_10min_first_high_bank);
  RUN_TEST(test_zone48_240min_both_maxima);
  RUN_TEST(test_zone20_120min);
  RUN_TEST(test_zone7_1min_minimum_duration);
  RUN_TEST(test_stop_zone1);
  RUN_TEST(test_stop_zone3);
  RUN_TEST(test_stop_zone48);
  RUN_TEST(test_start_rejects_zero_minutes);
  RUN_TEST(test_start_rejects_out_of_range);
  RUN_TEST(test_stop_rejects_out_of_range);
  RUN_TEST(test_every_valid_start_differs_from_its_stop);
  return UNITY_END();
}
